/**
 * Reporting-guideline checklists, item wording exactly as published by each
 * guideline group (see source, citation and licence on each). Generated from the
 * official checklist files; do not edit the wording by hand.
 */

export interface ChecklistItem {
  id: string;
  section: string;
  /** Shared opening words for a group of sub-items (e.g. ARRIVE 1a, 1b). */
  lead?: string;
  text: string;
}

export interface ReportingChecklist {
  id: "prisma" | "consort" | "strobe" | "arrive";
  name: string;
  fullName: string;
  studyTypes: string;
  citation: string;
  licence: string;
  url: string;
  note: string;
  items: ChecklistItem[];
}

